#!/usr/bin/env bash
# Generated by Claude (Anthropic's AI assistant, via Claude Code), October 2026. See Tools/Publish/README.md.
# Builds a throwaway copy of the public project from the current working tree (committed or not),
# so it can be opened in Unity before anything is committed or exported.
#
#   Tools/Publish/preview-public.sh <target-dir> [public-repo]
#   e.g. Tools/Publish/preview-public.sh /d/repos/Va.Si.Li-Lab-preview /d/repos/Va.Si.Li-Lab-public
#
# Uses the same path lists as export-public.sh. Re-running refreshes the copy but keeps its Library
# folder (and Unity's Temp/Logs/UserSettings), so Unity only reimports what changed.
set -euo pipefail

TARGET=${1:?target directory}
PUBLIC_REPO=${2:-}
HERE=$(cd "$(dirname "$0")" && pwd)
cd "$(git -C "$HERE" rev-parse --show-toplevel)"
MARKER=".vasili-public-preview"

# Never clobber a folder this script didn't create
if [ -d "$TARGET" ] && [ -n "$(ls -A "$TARGET")" ] && [ ! -f "$TARGET/$MARKER" ]; then
    echo "$TARGET exists and is not a preview folder, aborting"; exit 1
fi
mkdir -p "$TARGET"
# Keep Unity's own folders and files (the preview may be open in Unity)
find "$TARGET" -mindepth 1 -maxdepth 1 ! -name Library ! -name Temp ! -name Logs ! -name UserSettings ! -name obj ! -name .vs ! -name '*.csproj' ! -name '*.sln' ! -name "$MARKER" -exec rm -rf {} +
touch "$TARGET/$MARKER"

# Turn the filter-repo path lists into grep patterns
include=$(grep -v '^\s*$' "$HERE/public-paths.txt" | sed -E 's/[.[\*^$()+?{|]/\\&/g; s#^#^#; s#([^/])$#\1$#' | paste -sd'|')
exclude=$(grep -v '^\s*$' "$HERE/public-exclude.txt" | sed 's/^regex://' | paste -sd'|')

echo "== Copying public files to $TARGET"
git ls-files -co --exclude-standard -z \
    | tr '\0' '\n' | grep -E "$include" | grep -vE "$exclude" \
    | while IFS= read -r f; do [ -f "$f" ] && printf '%s\0' "$f"; done \
    | tar --null -T - -cf - | tar -xf - -C "$TARGET"

echo "== Scrubbing (same rules as public-replace.txt)"
sed -i -E "s/^(\s*AndroidKeystoreName: ).*/\1''/" "$TARGET/ProjectSettings/ProjectSettings.asset"
[ -f "$TARGET/Assets/Resources/OculusPlatformSettings.asset" ] && \
    sed -i -E 's/^(\s*ovr(Mobile)?AppID: ).*/\1/' "$TARGET/Assets/Resources/OculusPlatformSettings.asset"
grep -rlE 'credential' --include=*.cs --include=*.unity --include=*.prefab --include=*.asset "$TARGET/Assets" 2>/dev/null \
    | while IFS= read -r f; do sed -i -E 's/(credential\w*\s*=\s*")[^"]+"/\1"/I; s/^(\s*credential: )\S+$/\1/I' "$f"; done

if [ -n "$PUBLIC_REPO" ]; then
    echo "== Adding public-only files from $PUBLIC_REPO"
    for p in README.md LICENSE CITATION.cff Documentation .github .gitignore .gitattributes; do
        git -C "$PUBLIC_REPO" ls-files -z -- "$p" | tar -C "$PUBLIC_REPO" --null -T - -cf - | tar -xf - -C "$TARGET"
    done
fi

echo "== Done: $(find "$TARGET" -path "$TARGET/Library" -prune -o -type f -print | wc -l) files"
echo "   Open $TARGET in Unity Hub (Add > Add project from disk)."
